package com.fintrack.controller; import com.fintrack.model.Transaction; import com.fintrack.service.CurrentUser; import com.fintrack.repository.TransactionRepository; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{private final TransactionRepository repo;private final CurrentUser current;public DashboardController(TransactionRepository r,CurrentUser c){repo=r;current=c;}@GetMapping public Map<String,Object> data(Authentication a){var u=current.get(a);var tx=repo.findByUserIdOrderByTransactionDateDesc(u.getId());BigDecimal income=tx.stream().filter(x->x.getType()==Transaction.TransactionType.INCOME).map(Transaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal expense=tx.stream().filter(x->x.getType()==Transaction.TransactionType.EXPENSE).map(Transaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object> m=new LinkedHashMap<>();m.put("user",Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"phone",u.getPhone()==null?"":u.getPhone()));m.put("totalIncome",income);m.put("totalExpenses",expense);m.put("totalSavings",income.subtract(expense));m.put("totalBalance",income.subtract(expense));m.put("recentTransactions",tx.stream().limit(6).toList());return m;}}
